const response = await fetch("https://api.tandem.example/v1/projects", {
  headers: { Authorization: `Bearer ${process.env.TANDEM_API_KEY}` },
})

if (!response.ok) throw new Error(`Tandem API: ${response.status}`)

const { projects } = await response.json()
console.log(projects.map((project) => project.name))
